def solve(xs: list[int]) -> int:
    if not xs:
        return 0
    up = 1
    down = 1
    for i in range(1, len(xs)):
        if xs[i] > xs[i-1]:
            up = down + 1
        elif xs[i] < xs[i-1]:
            down = up + 1
    return max(up, down)

def solve(xs: list[int]) -> int:
    n = len(xs)
    if n == 0:
        return 0
    total = 0
    for i, x in enumerate(xs):
        w = ((i + 1) % n) + 1
        total += x * w
    return total % 97
